<?php
declare(strict_types=1);
namespace Giftcheta\Modules\Cart;

use Giftcheta\Modules\Commerce\ProductCustomizationValidator;
use Giftcheta\Modules\Commerce\ProductPricingService;
use PDO;

final class CartService
{
    public function __construct(private readonly PDO $db,private readonly CartRepository $repository,private readonly CartFileStorage $files) {}

    public function count(string $keyHash): int { $id=$this->repository->cartId($keyHash);return $id===null?0:$this->repository->count($id); }
    public function cartId(string $keyHash,bool $create=false): ?int { return $this->repository->cartId($keyHash,$create); }
    public function discardUnattached(int $cartId): void { $this->removeUnusedFiles($cartId); }

    public function summary(string $keyHash): array
    {
        $cartId=$this->repository->cartId($keyHash);if($cartId===null)return ['items'=>[],'count'=>0,'subtotal_cents'=>0];$this->repository->touch($cartId);$items=$this->repository->itemRows($cartId);$subtotal=0;
        foreach($items as &$item){$issue=null;$productAvailable=$item['product_status']==='active'&&$item['product_deleted_at']===null;$variantId=$item['product_variant_id']===null?null:(int)$item['product_variant_id'];$variant=null;
            if(!$productAvailable)$issue='Продуктът вече не е активен.';
            elseif((bool)$item['has_active_variants']&&$variantId===null)$issue='Изберете отново продуктов вариант.';
            elseif($variantId!==null&&(!(bool)$item['variant_active']||$item['variant_name']===null))$issue='Избраният вариант вече не е наличен.';
            if($variantId!==null)$variant=['price'=>$item['variant_price'],'price_adjustment'=>$item['variant_price_adjustment']];
            $available=$variantId!==null?ProductPricingService::available(['is_available'=>$item['variant_is_available'],'inventory_mode'=>$item['variant_inventory_mode'],'stock_quantity'=>$item['variant_stock_quantity']]):ProductPricingService::available(['is_available'=>$item['product_is_available'],'inventory_mode'=>$item['product_inventory_mode'],'stock_quantity'=>$item['product_stock_quantity']]);
            if(!$available&&$issue===null)$issue='Продуктът или вариантът е изчерпан.';
            $availableQuantity=$variantId!==null?ProductPricingService::availableQuantity(['inventory_mode'=>$item['variant_inventory_mode'],'stock_quantity'=>$item['variant_stock_quantity']]):ProductPricingService::availableQuantity(['inventory_mode'=>$item['product_inventory_mode'],'stock_quantity'=>$item['product_stock_quantity']]);
            if($availableQuantity!==null&&(int)$item['quantity']>$availableQuantity&&$issue===null)$issue='Количеството в количката надвишава текущата наличност.';
            $customInput=[];foreach($item['customizations'] as $row)if($row['customization_field_id']!==null)$customInput[]=['field_id'=>(int)$row['customization_field_id'],'value'=>$row['value_text'],'file_reference'=>$row['file_reference']];
            $validation=ProductCustomizationValidator::validate($this->db,(int)$item['product_id'],$customInput,function(string $reference,array $field)use($cartId,$item):bool{return $this->repository->uploadOwned($cartId,(int)$item['product_id'],(int)$field['id'],$reference,(int)$item['id'])!==null&&$this->files->path($reference)!==null;},$item['fields']);
            if(!$validation['ok']&&$issue===null)$issue='Персонализационните настройки са променени. Прегледайте реда преди продължаване.';
            $unitCents=ProductPricingService::unitPrice(['price'=>$item['product_price'],'sale_price'=>$item['product_sale_price']],$variant);$customCents=$validation['ok']?array_sum(array_column($validation['customizations'],'price_cents')):array_sum(array_map(static fn(array $row):int=>ProductPricingService::moneyCents((string)$row['price_adjustment'])??0,$item['customizations']));
            if($unitCents===null)$issue??='Цената на продукта не може да бъде изчислена.';else{$current=$unitCents+$customCents;$saved=ProductPricingService::moneyCents((string)$item['unit_price'])??0;$item['price_changed']=$current!==$saved;if($item['price_changed'])$this->repository->updatePrice((int)$item['id'],ProductPricingService::formatCents($current));$item['unit_price_current_cents']=$current;$subtotal+=$current*(int)$item['quantity'];}
            if($unitCents===null){$saved=ProductPricingService::moneyCents((string)$item['unit_price'])??0;$item['unit_price_current_cents']=$saved;$subtotal+=$saved*(int)$item['quantity'];$item['price_changed']=false;}
            $item['issue']=$issue;$item['available']=$issue===null;$item['line_total_cents']=$item['unit_price_current_cents']*(int)$item['quantity'];$item['variant_options']=json_decode((string)$item['variant_options'],true)?:[];$item['customization_map']=[];
            foreach($item['customizations'] as $custom){$fieldId=$custom['customization_field_id'];if($fieldId!==null)$item['customization_map'][(int)$fieldId]=$custom;$custom['preview_url']=$custom['file_reference']?'/cart/files/'.$custom['file_reference']:null;$item['custom_display'][]=$custom;}
        }unset($item);return ['items'=>$items,'count'=>array_sum(array_map(static fn(array $i):int=>(int)$i['quantity'],$items)),'subtotal_cents'=>$subtotal];
    }

    public function add(string $keyHash,int $productId,?int $variantId,int $quantity,array $input): array
    { if($quantity<1||$quantity>999)return $this->error('Количеството трябва да е между 1 и 999.',422);$cartId=$this->repository->cartId($keyHash,true);if($cartId===null)return $this->error('Количката не можа да бъде създадена.',500);$product=$this->repository->product($productId);if(!$product||$product['status']!=='active'||$product['deleted_at']!==null)return $this->error('Продуктът не е наличен.',404);$variant=$this->chooseVariant($productId,$variantId);if(isset($variant['ok'])&&!$variant['ok'])return $variant;$stock=$variantId!==null?$variant:$product;if(!ProductPricingService::available($stock))return $this->error('Продуктът или вариантът е изчерпан.',409);$available=ProductPricingService::availableQuantity($stock);if($available!==null&&$quantity>$available)return $this->error('Избраното количество надвишава наличността.',409);
        $validation=$this->validate($cartId,$productId,$input,null);if(!$validation['ok'])return $validation;$unit=ProductPricingService::unitPrice($product,$variantId===null?null:$variant);if($unit===null)return $this->error('Цената на продукта е невалидна.',409);$extra=array_sum(array_column($validation['customizations'],'price_cents'));$signature=$this->signature($cartId,$productId,$validation['customizations']);$price=ProductPricingService::formatCents($unit+$extra);$this->db->beginTransaction();try{$same=$this->repository->sameItem($cartId,$productId,$variantId,$signature);if($same){$newQty=(int)$same['quantity']+$quantity;if($newQty>999||($available!==null&&$newQty>$available)){ $this->db->rollBack();return $this->error('Количеството в количката надвишава наличността.',409);}$this->repository->updateQuantity((int)$same['id'],$newQty);$this->repository->updatePrice((int)$same['id'],$price);$this->repository->touch($cartId);$this->db->commit();$this->removeUnusedFiles($cartId);return ['ok'=>true,'message'=>'Продуктът е добавен в количката.'];}
            $key=bin2hex(random_bytes(16));$itemId=$this->repository->insertItem($cartId,$key,$productId,$variantId,$product['name'],$variantId===null?null:(string)$variant['name'],$signature,$quantity,$price);$this->repository->saveCustomizations($itemId,$this->storageRows($validation['customizations']));foreach($validation['customizations'] as $row)if($row['file_reference'])$this->repository->attachUpload($cartId,$itemId,(int)$row['field_id'],$row['file_reference']);$this->repository->touch($cartId);$this->db->commit();return ['ok'=>true,'message'=>'Продуктът е добавен в количката.'];
        }catch(\Throwable $error){if($this->db->inTransaction())$this->db->rollBack();throw $error;} }

    public function setQuantity(string $keyHash,string $key,int $quantity): array
    { $cartId=$this->repository->cartId($keyHash);$item=$cartId?$this->repository->item($cartId,$key):null;if(!$cartId||!$item)return $this->error('Редът в количката не е намерен.',404);if($quantity<1||$quantity>999)return $this->error('Количеството трябва да е между 1 и 999.',422);$product=$this->repository->product((int)$item['product_id']);if(!$product||$product['status']!=='active'||$product['deleted_at']!==null)return $this->error('Продуктът вече не е наличен.',409);$variantId=$item['product_variant_id']===null?null:(int)$item['product_variant_id'];$variant=$this->chooseVariant((int)$item['product_id'],$variantId);if(isset($variant['ok'])&&!$variant['ok'])return $variant;$stock=$variantId===null?$product:$variant;if(!ProductPricingService::available($stock))return $this->error('Продуктът или вариантът е изчерпан.',409);$available=ProductPricingService::availableQuantity($stock);if($available!==null&&$quantity>$available)return $this->error('Избраното количество надвишава наличността.',409);$this->repository->updateQuantity((int)$item['id'],$quantity);$this->repository->touch($cartId);return ['ok'=>true,'message'=>'Количеството е обновено.']; }

    public function updateCustomizations(string $keyHash,string $key,?int $variantId,array $input): array
    { $cartId=$this->repository->cartId($keyHash);$item=$cartId?$this->repository->item($cartId,$key):null;if(!$cartId||!$item)return $this->error('Редът в количката не е намерен.',404);$product=$this->repository->product((int)$item['product_id']);if(!$product||$product['status']!=='active'||$product['deleted_at']!==null)return $this->error('Продуктът вече не е наличен.',409);$variant=$this->chooseVariant((int)$item['product_id'],$variantId);if(isset($variant['ok'])&&!$variant['ok'])return $variant;$stock=$variantId===null?$product:$variant;if(!ProductPricingService::available($stock))return $this->error('Продуктът или вариантът е изчерпан.',409);$qty=(int)$item['quantity'];$available=ProductPricingService::availableQuantity($stock);if($available!==null&&$qty>$available)return $this->error('Количеството в количката надвишава наличността.',409);
        $validation=$this->validate($cartId,(int)$item['product_id'],$input,(int)$item['id']);if(!$validation['ok'])return $validation;$unit=ProductPricingService::unitPrice($product,$variantId===null?null:$variant);if($unit===null)return $this->error('Цената на продукта е невалидна.',409);$price=ProductPricingService::formatCents($unit+array_sum(array_column($validation['customizations'],'price_cents')));$signature=$this->signature($cartId,(int)$item['product_id'],$validation['customizations'],(int)$item['id']);$this->db->beginTransaction();try{$same=$this->repository->sameItem($cartId,(int)$item['product_id'],$variantId,$signature,(int)$item['id']);if($same){$newQty=(int)$same['quantity']+$qty;if($newQty>999||($available!==null&&$newQty>$available)){$this->db->rollBack();return $this->error('Количеството в еднаквите редове надвишава наличността.',409);}$this->repository->updateQuantity((int)$same['id'],$newQty);$this->repository->updatePrice((int)$same['id'],$price);$this->repository->deleteItem($cartId,(int)$item['id']);}else{$this->repository->updateVariant((int)$item['id'],$variantId,$variantId===null?'':(string)$variant['name'],$signature,$price);$this->repository->saveCustomizations((int)$item['id'],$this->storageRows($validation['customizations']));foreach($validation['customizations'] as $row)if($row['file_reference'])$this->repository->attachUpload($cartId,(int)$item['id'],(int)$row['field_id'],$row['file_reference']);}$this->repository->touch($cartId);$this->db->commit();$this->removeUnusedFiles($cartId);return ['ok'=>true,'message'=>'Персонализацията е обновена.'];}catch(\Throwable $error){if($this->db->inTransaction())$this->db->rollBack();throw $error;} }

    public function remove(string $keyHash,string $key): array
    { $cartId=$this->repository->cartId($keyHash);$item=$cartId?$this->repository->item($cartId,$key):null;if(!$cartId||!$item)return $this->error('Редът в количката не е намерен.',404);$refs=array_values(array_filter(array_column($item['customizations'],'file_reference')));$this->repository->deleteItem($cartId,(int)$item['id']);$this->files->delete($refs);$this->removeUnusedFiles($cartId);return ['ok'=>true,'message'=>'Продуктът е премахнат от количката.']; }

    public function editItem(string $keyHash,string $key): ?array
    { $cartId=$this->repository->cartId($keyHash);if(!$cartId)return null;$item=$this->repository->item($cartId,$key);if(!$item)return null;$item['customization_map']=[];foreach($item['customizations'] as $row)if($row['customization_field_id']!==null)$item['customization_map'][(int)$row['customization_field_id']]=$row;return $item; }

    public function file(string $keyHash,string $reference): ?array
    { $cartId=$this->repository->cartId($keyHash);if(!$cartId)return null;$record=$this->repository->uploadForView($cartId,$reference);$path=$record?$this->files->path($reference):null;return $record&&$path?['path'=>$path,'mime'=>$record['mime_type']]:null; }

    private function validate(int $cartId,int $productId,array $input,?int $itemId): array
    { return ProductCustomizationValidator::validate($this->db,$productId,$input,function(string $reference,array $field)use($cartId,$productId,$itemId):bool{return $this->repository->uploadOwned($cartId,$productId,(int)$field['id'],$reference,$itemId)!==null&&$this->files->path($reference)!==null;}); }
    private function chooseVariant(int $productId,?int $variantId): array
    { $variants=$this->repository->variants($productId);if($variants&&$variantId===null)return $this->error('Изберете продуктов вариант.',422);if(!$variants&&$variantId!==null)return $this->error('Избраният продукт няма варианти.',422);if($variantId!==null){$variant=$this->repository->variant($productId,$variantId);if(!$variant||!(int)$variant['is_active'])return $this->error('Избраният продуктов вариант не е валиден.',422);return $variant;}return []; }
    private function signature(int $cartId,int $productId,array $rows,?int $itemId=null): string
    { $normalized=[];foreach($rows as $row){$fileHash=null;if($row['file_reference'])$fileHash=$this->repository->uploadOwned($cartId,$productId,(int)$row['field_id'],$row['file_reference'],$itemId)['content_hash']??$row['file_reference'];$normalized[]=['field_id'=>(int)$row['field_id'],'type'=>$row['type'],'value'=>$row['value'],'image'=>$fileHash];}usort($normalized,static fn(array $a,array $b):int=>$a['field_id']<=>$b['field_id']);return hash('sha256',json_encode($normalized,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)); }
    private function storageRows(array $rows): array { return array_map(static fn(array $row):array=>['field_id'=>$row['field_id'],'label'=>$row['label'],'type'=>$row['type'],'value'=>$row['value'],'file_reference'=>$row['file_reference'],'price'=>ProductPricingService::formatCents($row['price_cents'])],$rows); }
    private function removeUnusedFiles(int $cartId): void { $q=$this->db->prepare('SELECT u.file_reference FROM cart_uploads u LEFT JOIN cart_item_customizations c ON c.file_reference=u.file_reference WHERE u.cart_id=? AND c.id IS NULL');$q->execute([$cartId]);$refs=$q->fetchAll(PDO::FETCH_COLUMN);if($refs){$p=implode(',',array_fill(0,count($refs),'?'));$this->db->prepare("DELETE FROM cart_uploads WHERE cart_id=? AND file_reference IN ({$p})")->execute([$cartId,...$refs]);$this->files->delete($refs);} }
    private function error(string $message,int $status): array { return ['ok'=>false,'message'=>$message,'status'=>$status,'code'=>'cart_error']; }
